"""All vector-space and operator questions, retaining explicit coordinate orders."""
import manual_solutions as author
from matrix_workings import sp,L,inverse,determinant
from linear_algebra_chapter_two import visible,multiply
from linear_algebra_chapter_three import system,row_work,matrix_equation
from linear_algebra_chapter_four import V,column_basis

def put(n,steps,errors):
 author.add('LA7',f'006-{n:03}',steps,errors,'检查空间公理、全部小问、基的独立与生成、坐标方向及变换矩阵每一列。')
 author.PATCHES[f'SRC-LA7-E006-{n:03}']['supersedes_computed_supplement']=True
def example(n,steps,errors):
 author.add_example('LA7',n,steps,errors,'证明空间与映射的条件，检查基顺序、坐标和像向量逐列表示。')
 author.PATCHES['SRC-LA7-X'+n]['supersedes_computed_supplement']=True

def coordinate_change(A,B,label):
 assert A.det()!=0 and B.det()!=0
 C=B.inv()*A;R=A.inv()*B;assert C*R==sp.eye(A.rows)
 out=[f'**{label}。** 用相同参照基把两组基向量逐列排为A、B。同一向量标准系数满足Ax=Bx′，因此新坐标x′=B⁻¹Ax，反向x=A⁻¹Bx′。注意坐标公式的乘数与B=AP中的过渡矩阵互逆。']
 out+=matrix_equation(B,A,'解BC=A，直接得到坐标变换乘数C')
 out+=matrix_equation(A,B,'解AR=B，得到逆向乘数R')
 out+=[r'所以 $$x\prime='+L(C)+r'x,\qquad x='+L(R)+r'x\prime.$$两乘数互逆，CR=RC=I；代回Bx′=Ax给同一向量。']
 return out

put(1,[r'第（1）任意2阶矩阵[[a,b],[c,d]]含零矩阵，两个这样的矩阵相加、任意实数倍仍为2阶，运算律由实数逐元素运算继承。每个矩阵唯一分解为aE₁₁+bE₁₂+cE₂₁+dE₂₂，四系数为0才得零阵，所以四个矩阵独立且生成全体，维数4。',r'第（2）迹零要求d=−a，所以矩阵为[[a,b],[c,−a]]。零阵在内，tr(M+N)=trM+trN=0、tr(kM)=k·0=0，因而是子空间。唯一分解a·diag(1,−1)+bE₁₂+cE₂₁，三基向量独立，维数3。',r'第（3）对称矩阵为[[a,b],[b,d]]，零阵对称，(M+N)ᵀ=M+N、(kM)ᵀ=kM，封闭为子空间。唯一分解aE₁₁+dE₂₂+b(E₁₂+E₂₁)，三者独立并生成，维数3。',r'以上“唯一分解”同时核对基的两个条件：每个空间元素能表示，且零表示仅全零系数。这里基元素本身是矩阵，不是把它们改称二维列向量。'],[r'对称的两个非对角位置共享一个系数，维数不是4。',r'空间有零元素并不代表一个合法基可包含零矩阵。'])
put(2,[r'与e₃不平行的向量集合若为向量空间，至少要对通常加法封闭。取u=(1,0,0)ᵀ、v=(−1,0,1)ᵀ，它们都含非零第一分量，不是e₃的标量倍。',r'但u+v=(0,0,1)ᵀ=e₃，与e₃平行，故和不在集合。两个合法元素相加离开集合已否定封闭性，因此不构成线性空间。',r'这个反例不依赖“零向量是否称平行”的语言约定；和是明确的非零e₃。不要因集合中有许多不同方向就误以为能成为子空间。'],[r'否定封闭应选两个都属于原集合的向量，再检查其和不属于。',r'使用非零轴向反例可避开零向量平行性的约定差异。'])
A=V([1,1,0,0],[0,1,1,0],[1,0,0,1],[2,2,1,1]);B=V([-1,1,0,0],[1,0,-1,0],[-2,2,1,0],[0,0,0,1])
put(3,[r'固定共同参照基(1,x,x²,x³)，P[x]₃中每个多项式由4个系数唯一决定，所以维数4。四个多项式是基当且仅当其4阶系数列矩阵满秩。',r'第（1）第四个多项式恰等于前3个之和，给非平凡关系p₁+p₂+p₃−p₄=0，故相关，不是基。']+row_work(A,'第（1）系数矩阵核验')+row_work(B,'第（2）系数矩阵')+[r'第（2）化为4阶单位阵，系数列独立，又有4列，必张成4维多项式空间，所以是一个基。'],[r'P[x]₃是次数不超过3，维数4，不是3。',r'系数排列可升幂或降幂，但同一题各列必须一致。'])
A=V([1,3,5],[6,3,2],[3,1,0]);b=sp.Matrix([7,3,1])
put(4,[r'设所求坐标为c=(c₁,c₂,c₃)ᵀ，则α=c₁a₁+c₂a₂+c₃a₃，即Ac=α。']+system(A,b,'解基坐标')+[r'唯一解c=(1,−2,6)ᵀ。直接相加(1,3,5)−2(6,3,2)+6(3,1,0)=(7,3,1)，确为原α。'],[r'目标α的标准坐标(7,3,1)与在新基的坐标不同。',r'基向量排A的列，而不是按行。'])
A=V([1,2,1],[2,3,3],[3,7,-2]);B=V([3,1,4],[5,2,1],[1,1,-6])
put(5,coordinate_change(A,B,'两个三维基的坐标公式'),[r'求α基坐标到β基坐标，应使用B⁻¹A，不能把A⁻¹B方向写反。',r'正向和反向矩阵应互逆，不能只靠看数值相似核对。'])
P=V([2,1,-1,1],[0,3,1,0],[5,3,2,1],[6,6,1,3])
put(6,[r'第（1）旧基为单位阵E，新基矩阵恰为题给向量逐列排成的P，B=EP=P，所以过渡矩阵 $$P='+L(P)+r'.$$',r'第（2）给定向量的标准坐标为x，新基坐标z由Pz=x确定，即z=P⁻¹x。以下完整求逆。']+inverse(P)[0]+[r'因此 $$z='+L(P.inv())+r'x.$$第（3）“两个基同坐标”指z=x，代入Pz=x得(P−I)x=0，而非令P本身等于I。']+system(P-sp.eye(4),sp.zeros(4,1),'全部同坐标向量')+[r'通解可写k(1,1,1,−1)ᵀ，含k=0的零向量。因为旧基是标准基，这个系数列也正是向量本身。'],[r'过渡矩阵P与新坐标公式P⁻¹方向不同。',r'同坐标只要求该向量被P固定，不要求所有向量坐标都不变。'])
M=visible('E006-007');cols=[sp.Matrix(list(A)) for A in M];A=sp.Matrix.hstack(*cols[:2])
put(7,[r'把2阶矩阵按固定顺序(11,12,21,22)展开成4维列向量。这是保持加法数乘的一一对应，矩阵线性表示等价于这4个位置的系数方程。']+system(A,cols[2],'第（1）表示b₁')+system(A,cols[3],'第（1）表示b₂')+column_basis(sp.Matrix.hstack(*cols),'第（2）四矩阵展开后的列组')+[r'主元列对应原a₁、a₂、b₂，故它们是矩阵空间L的一个基，dimL=3。b₁=2a₁+a₂只是冗余方向，不再增加维数。'],[r'2阶矩阵是4维系数对象，不能只检查两个行或某两个元素。',r'找到b₂不可表示不等于四个全独立，还要利用b₁关系。'])
put(8,[r'第（1）T(x,y)=(−x,y)，保持y、反转x，每一点到y轴两侧的距离相等，故关于y轴反射。固定点正是x=0。',r'第（2）T(x,y)=(0,y)，删除x分量，像落在y轴且位移沿垂直于y轴的x方向，故正交投影到y轴；这是不可逆投影，不是反射。',r'第（3）T(x,y)=(y,x)，交换两坐标，保持直线y=x上的点，沿法线(1,−1)反号，故关于y=x反射。',r'第（4）T(x,y)=(y,−x)。标准基e₁映为−e₂、e₂映为e₁，保持长度、原点固定，极角减少π/2，故绕原点顺时针90°旋转。'],[r'第（2）投影会压掉一个方向，不应称镜像。',r'用e₁=(1,0)的像能快速判顺逆时针，防止符号颠倒。'])
put(9,[r'先检查映射是否确实落回V。若Aᵀ=A，则(PᵀAP)ᵀ=PᵀAᵀP=PᵀAP，仍对称，所以T:V→V定义良好。',r'对V中A、B及任意实数k、l，T(kA+lB)=Pᵀ(kA+lB)P=kPᵀAP+lPᵀBP=kT(A)+lT(B)，满足保持任意线性组合，故T为线性变换。',r'P可逆还给T可逆：若C=T(A)，左乘P⁻ᵀ、右乘P⁻¹得A=P⁻ᵀCP⁻¹，同样对称。可逆性用于这一额外结论；单就线性而言任意固定P都满足。'],[r'既要保持线性组合，也要证明输出仍在对称矩阵空间内。',r'这里T是矩阵空间上的算子，PᵀAP不是T在某个矩阵基下的坐标矩阵。'])
put(10,[r'先算各基函数的导数，须用乘积法则：D(x²eˣ)=(x²+2x)eˣ=α₁+2α₂，D(xeˣ)=(x+1)eˣ=α₂+α₃，D(eˣ)=eˣ=α₃。',r'三个像在给定顺序α₁、α₂、α₃下的坐标列依次(1,2,0)ᵀ、(0,1,1)ᵀ、(0,0,1)ᵀ。把像坐标按列拼成 $$[D]_\alpha=\begin{pmatrix}1&0&0\\2&1&0\\0&1&1\end{pmatrix}.$$',r'核验一般f=(a₂x²+a₁x+a₀)eˣ：导数系数列为(a₂,2a₂+a₁,a₁+a₀)ᵀ，恰等于该矩阵乘原坐标(a₂,a₁,a₀)ᵀ，所以矩阵对任意f正确。'],[r'eˣ也要求导，不能只微分多项式。',r'像的坐标按列，不是把三个像当成矩阵的三行。'])
L0=sp.Matrix([[1,0],[1,1]]);basis=[sp.Matrix([[1,0],[0,0]]),sp.Matrix([[0,1],[1,0]]),sp.Matrix([[0,0],[0,1]])]
steps=[r'对称矩阵[[a,b],[b,c]]在给定基下坐标为(a,b,c)ᵀ，其中b是单个共享非对角系数。逐一计算三个基矩阵的像。']
for i,A in enumerate(basis,1):
 B=L0*A*L0.T
 steps+=multiply(L0,A,r'LA_{'+str(i)+'}')+multiply(L0*A,L0.T,r'T(A_{'+str(i)+'})')+['该像的坐标是 $$'+L(sp.Matrix([B[0,0],B[0,1],B[1,1]]))+r'.$$']
put(11,steps+[r'将这三个坐标依次按列排，$$[T]=\begin{pmatrix}1&0&0\\1&1&0\\1&2&1\end{pmatrix}.$$其三列分别对应T(A₁)、T(A₂)、T(A₃)，与原基顺序一致。'],[r'A₂两个非对角1一起组成一个基向量，不应给它两个独立坐标。',r'3维矩阵空间中的T坐标矩阵为3阶，不是题设乘法用的2阶L。'])
T=sp.Matrix([[1,0,sp.Rational(1,2)],[0,1,-sp.Rational(1,2)],[0,0,sp.Rational(1,2)]])
put(12,[r'第（1）每个输出系数都是输入a₀、a₁、a₂的齐次一次组合，因此对p、q和任意实数k、l逐系数代入，T(kp+lq)=kT(p)+lT(q)。输出仍次数≤2，所以是V上的线性变换。',r'第（2）T(1)=1，T(x)=x，T(x²)=(1−x+x²)/2，三个像的坐标按列排为 $$[T]='+L(T)+r'.$$',r'第（3）若W所有p均满足T(p)=p，则W包含于固定点空间ker(T−I)。应先解全部固定点，再取其最大子空间，不能任意选一两个例子就宣布最大。']+system(T-sp.eye(3),sp.zeros(3,1),'固定点的全部系数')+[r'得到a₂=0，a₀、a₁任意，故固定点空间span{1,x}维数2。任意合格W维数≤2；取W等于这个空间达到2，故最大值2。'],[r'最大维数需要上界和可达到例子两步。',r'固定点集合解的是(T−I)c=0，不是Tc=0。'])
put(13,[r'A²=A表示T²=T，与基无关。任意v可写v=Tv+(v−Tv)，前项属于ImT，后项因T(v−Tv)=Tv−T²v=0而属于kerT，所以V=ImT+kerT。',r'若w同时在两空间中，写w=Tu且Tw=0，又Tw=T²u=Tu=w，故w=0。交只有0，所以这个和是直和，两个子空间的基拼接后独立且生成V。',r'设ImT基u₁至u_r、kerT基v₁至v_{n−r}。在像空间Tuᵢ=uᵢ，在核Tvⱼ=0，因此新基下各像坐标按列给 $$[T]_{new}=\operatorname{diag}(I_r,0_{n-r}).$$',r'r=0时T=0，r=n时T=I，同一结论含这两个边界。证明通过像与核直接构造所需基，不必预先假定A已经可对角化。'],[r'仅有V=ImT+kerT不够，必须证明交为0，拼接的基才独立。',r'在像上T为恒等来自幂等性质，在任意线性变换上并非如此。'])

example('147-4242',[r'次数≤n允许最高若干系数为0，也包含零多项式。任意p=∑aᵢxⁱ、q=∑bᵢxⁱ相加为∑(aᵢ+bᵢ)xⁱ，仍无高于n次项；λp=∑λaᵢxⁱ同样在集合内。',r'多项式的通常加法数乘按每个实系数进行，交换、结合、分配、单位数乘规律由实数运算继承，零元素为零多项式、负元为逐系数相反数，所以是实向量空间。',r'基1,x,…,xⁿ生成所有此类多项式；一个零多项式的每个系数都0，故基独立，维数n+1。n=0时为常数多项式的一维空间。'],[r'次数不超过n的空间维数n+1，常数项贡献一个方向。',r'最高系数允许0，否则零元与封闭性会失败。'])
example('147-6187',[r'恰为n次要求最高系数非零，因此零多项式不在集合。向量空间必须含加法零元，已不满足。',r'具体取p=xⁿ，p在集合；但数乘0p=0不在集合，所以数乘不封闭。即使不使用零数乘，p与−p都在集合却和为0，也否定加法封闭。',r'所以不是向量空间。不要把本题“恰为n次”与上一例“次数≤n”的集合混淆，后者允许最高项消失。'],[r'加法可使最高次项抵消，不能声称次数总保持n。',r'一个失败的向量空间条件已足够否定。'])
example('147-7378',[r'展开A sin(x+B)=A sinB·cosx+A cosB·sinx，所以集合包含于span{cosx,sinx}。',r'反向对任意a cosx+b sinx，若a=b=0取A=0；否则取A=√(a²+b²)>0，并选相位B使sinB=a/A、cosB=b/A，就写成A sin(x+B)。故集合正等于这个张成空间。',r'张成空间对通常函数加法数乘封闭，零函数取A=0，继承函数运算规律，因而是向量空间。cosx、sinx独立：在x=0与π/2代入零组合分别给系数为0，所以维数2。'],[r'要证明集合等于张成空间，三角展开只给一个包含，还要写振幅相位的反向构造。',r'A允许0，零函数属于集合，不应擅自排除。'])
example('148-1946',[r'集合是通常Rⁿ，加法通常，新的数乘λ∘x恒等于零向量，所以加法、数乘两者确实封闭。',r'但取任一非零x，例如e₁，有1∘x=0≠x，违反向量空间数乘单位律1x=x。',r'因此不是向量空间。仅封闭的子空间判定法依赖继承原空间运算；此处改变了数乘，不能因为集合没变、封闭仍成立就跳过公理。'],[r'封闭性本身不能保证任意新运算满足向量空间公理。',r'应使用非零x作反例，x=0时单位律恰好成立，不能否定。'])
example('148-5197',[r'正数乘积及任意实次幂仍为正数，两运算封闭。⊕的交换和结合分别是ab=ba、(ab)c=a(bc)。',r'新加法零元为1，因为a⊕1=a；a的加法负元是1/a，因为a⊕(1/a)=1。这里的零元素不是实数0，0根本不在R⁺。',r'数乘单位律1∘a=a¹=a；结合律λ∘(μ∘a)=(a^μ)^λ=a^{λμ}=(λμ)∘a，正数条件保障实幂运算合法。',r'对标量加法的分配：(λ+μ)∘a=a^{λ+μ}=a^λa^μ=(λ∘a)⊕(μ∘a)。对新加法分配：λ∘(a⊕b)=(ab)^λ=a^λb^λ=(λ∘a)⊕(λ∘b)。因此全部线性空间公理成立。',r'可用log验证整体结构：log(a⊕b)=loga+logb，log(λ∘a)=λloga，log:R⁺→R为双射，故是到通常一维实空间的线性同构；一基可取e。'],[r'零元随运算定义改变，本题为1，负元为倒数。',r'实数幂与log使用正数域，不能把0或负数混入。'])
example('151-2168',[r'第一个基按升幂排列1,x,x²,x³,x⁴，所以直接比较多项式系数，坐标为(a₀,a₁,a₂,a₃,a₄)ᵀ。',r'第二个基下设p=c₁+c₂(1+x)+2c₃x²+c₄x³+c₅x⁴。比较常数与一次项：c₁+c₂=a₀、c₂=a₁；其余2c₃=a₂、c₄=a₃、c₅=a₄。',r'依次解得c₂=a₁、c₁=a₀−a₁、c₃=a₂/2，故新坐标(a₀−a₁,a₁,a₂/2,a₃,a₄)ᵀ。代入组合逐项还原原p，系数方程又保证唯一。'],[r'基1+x同时贡献常数与一次项，常数坐标须减a₁。',r'基向量为2x²，坐标应a₂/2，不是2a₂。'])
A=sp.Matrix([[1,1,-1,-1],[2,-1,2,-1],[-1,1,1,0],[0,1,1,1]]);B=sp.Matrix([[2,0,-2,1],[1,1,1,3],[0,2,1,1],[1,2,2,2]])
example('153-2890',[r'这里固定共同参照基的次序为(x³,x²,x,1)，与通常升幂排列不同。逐个读取原多项式各项系数，得到 $$A='+L(A)+r',\quad B='+L(B)+r'.$$']+coordinate_change(A,B,'多项式两组基的坐标转换'),[r'参照基取降幂时常数在最后一行，不能混用升幂系数。',r'从α到β坐标使用B⁻¹A；只有先写Ax=Bx′才容易看清方向。'])
example('155-7805',[r'第（1）导数仍次数≤3，所以D把V映入自身。求导的和法则、常数倍法则给D(p+q)=Dp+Dq、D(λp)=λDp，因此线性。',r'第（2）输出a₀是常数多项式，属于V。若q常数项b₀，则T(p+q)=a₀+b₀、T(λp)=λa₀，分别等于T(p)+T(q)、λT(p)，所以也是线性变换。',r'第（3）T₁(0)=1≠0，已违反线性变换必须将零映到零的必要条件；另T₁(p+q)=1而T₁(p)+T₁(q)=2，不保持加法，故不线性。'],[r'常数项提取是线性映射，常值为1的映射不是，两者不要混淆。',r'常数多项式仍在P[x]₃中，次数下降不破坏定义域到自身的要求。'])
example('156-3329',[r'对非零向量写x=r cosθ、y=r sinθ，其中r>0。矩阵乘法给新坐标(r cosθ cosφ−r sinθ sinφ，r cosθ sinφ+r sinθ cosφ)。',r'用和角公式合并成(r cos(θ+φ)，r sin(θ+φ))，故模r不变，极角增加φ。原点则直接代入矩阵得到仍为原点。',r'所以变换为绕原点按有符号角φ旋转：φ>0按逆时针理解，φ<0相当于顺时针转|φ|。取φ=π/2时e₁映为e₂可验证方向。'],[r'矩阵右上为−sinφ，对应逆时针正角，别与另一符号约定混淆。',r'原点无极角，要单独用矩阵检查。'])
example('157-2451',[r'矩阵分配律给T(u+v)=A(u+v)=Au+Av=T(u)+T(v)，数乘结合给T(λu)=λAu=λT(u)，且输出仍n维，故T是Rⁿ上的线性变换。',r'按列展开Ax=x₁α₁+⋯+x_nα_n，所以每个像在A列向量张成空间内；反向任意这样的组合也正是某个系数x的像，两个包含给ImT=span{α₁,…,α_n}。',r'核按定义是所有映成零的x，正是kerT={x:Ax=0}。因此dimImT=R(A)，dimkerT=n−R(A)，二者维数和为n，含A零或可逆的边界。'],[r'像空间的相等应给两个方向，不能只说每个Ax可展开。',r'核是输入x的集合，不是A的零列位置列表。'])
example('159-6671',[r'基顺序固定为x³,x²,x,1，依次求导Dp₁=3x²=3p₂，Dp₂=2x=2p₃，Dp₃=1=p₄，Dp₄=0。',r'四个像坐标依次(0,3,0,0)ᵀ、(0,0,2,0)ᵀ、(0,0,0,1)ᵀ、(0,0,0,0)ᵀ，按列排列 $$[D]=\begin{pmatrix}0&0&0&0\\3&0&0&0\\0&2&0&0\\0&0&1&0\end{pmatrix}.$$',r'用任意坐标(a₃,a₂,a₁,a₀)ᵀ乘得(0,3a₃,2a₂,a₁)ᵀ，表示导数3a₃x²+2a₂x+a₁，验证列排列与基顺序一致。'],[r'降幂基使非零元在次对角线下方，不要照搬升幂基的矩阵。',r'常数导数为零，最后一列全0但仍需保留。'])
A=sp.diag(1,1,0);P=V([1,0,0],[0,1,0],[1,1,1])
example('160-1715',[r'第（1）标准基下Ti=i、Tj=j、Tk=0，所以像坐标三列为e₁、e₂、0，得到diag(1,1,0)。',r'第（2）新基α=i、β=j、γ=i+j+k。Tα=α、Tβ=β、Tγ=i+j=α+β，像在新基下坐标为(1,0,0)ᵀ、(0,1,0)ᵀ、(1,1,0)ᵀ，故 $$[T]_{new}=\begin{pmatrix}1&0&1\\0&1&1\\0&0&0\end{pmatrix}.$$',r'核验换基：新基列矩阵 $$P='+L(P)+r'$$，用新坐标z先经P到标准坐标、再经A投影、最后P⁻¹回新坐标，所以新矩阵为P⁻¹AP。']+multiply(P.inv()*A,P,r'P^{-1}AP'),[r'同一变换在不同基下矩阵可以不同，不能一直照写diag(1,1,0)。',r'Tγ=i+j需在新基中表示成α+β，第三个坐标是0。'])
example('161-2167',[r'交换基顺序的过渡矩阵 $$P=\begin{pmatrix}0&1\\1&0\end{pmatrix},\quad P^2=I,\quad P^{-1}=P.$$新坐标z先经P变成旧坐标，旧矩阵A作用后再经P⁻¹，故B=P⁻¹AP。',r'右乘P先交换A的两列：AP=[[a₁₂,a₁₁],[a₂₂,a₂₁]]；再左乘P交换两行，得到 $$B=\begin{pmatrix}a_{22}&a_{21}\\a_{12}&a_{11}\end{pmatrix}.$$',r'也可直接按新基(α₂,α₁)排列像：Tα₂=a₂₂α₂+a₁₂α₁给第一列(a₂₂,a₁₂)ᵀ，Tα₁=a₂₁α₂+a₁₁α₁给第二列(a₂₁,a₁₁)ᵀ，与乘法一致。'],[r'换基要同时变换输入与输出坐标，应交换行和列，不能只交换一边。',r'这是相似变换P⁻¹AP，不是只对原矩阵转置。'])

